import numpy as np
import torch

_DTYPE_MAP = {
    "float16": torch.float16,
    "float32": torch.float32,
    "bfloat16": torch.bfloat16,
    "float64": torch.float64,
}


def gen_inputs(ctx, device):
    max_length = int(ctx["max_length"])
    batch_size = int(ctx["offsets__shape"][0]) - 1
    values_dtype = _DTYPE_MAP[ctx["values__dtype"]]

    np.random.seed(42)
    seq_lengths = np.random.randint(1, max_length + 1, size=batch_size).tolist()

    offsets_list = [0] + list(np.cumsum(seq_lengths).astype(int).tolist())
    offsets = torch.tensor(offsets_list, device=device, dtype=torch.int64)

    total_length = int(sum(seq_lengths))
    values = torch.randn(total_length, dtype=values_dtype, device=device)

    return {"values": values, "offsets": offsets}


def run(values, offsets, max_length, padding_value):
    return torch.ops.aten._jagged_to_padded_dense_forward(
        values, [offsets], [int(max_length)], padding_value
    )
